import orders from './orders.json' with {type:'json'};

const TOOL_NAME = 'order_status';
const inputSchema = {
  type: 'object',
  properties: {
    order_id: { type: 'string', description: 'The order identifier' },
    include_history: { type: 'boolean', default: false, description: 'When true, include the chronological history of the order' }
  },
  required: ['order_id'],
  additionalProperties: false
};

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description: 'Get the current status of an order. Returns the current status and, when requested, the chronological history.',
      inputSchema
    }
  ];
}

function validateArgs(args) {
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  const allowed = Object.keys(inputSchema.properties);
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error(`Invalid field: ${key}`);
    }
  }
  if (args.order_id === undefined) {
    throw new Error('Missing required field: order_id');
  }
  if (typeof args.order_id !== 'string') {
    throw new Error('order_id must be a string');
  }
  if (args.include_history !== undefined && typeof args.include_history !== 'boolean') {
    throw new Error('include_history must be a boolean');
  }
}

export async function callTool(name, args = {}) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }
  validateArgs(args);

  const order_id = args.order_id;
  const include_history = args.include_history === true;

  const order = orders[order_id];
  if (!order) {
    throw new Error(`Order not found: ${order_id}`);
  }

  let text = `Order ${order_id} status: ${order.status}`;
  if (include_history) {
    text += `\nHistory: ${order.history.join(', ')}`;
  }

  return {
    content: [{ type: 'text', text }]
  };
}

